{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Codeine, the closest structural analogue sharing the methoxy-morphinan scaffold, has an absolute oral bioavailability of 42–71% in healthy volunteers, directly supporting F ≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Codeine sulfate showed 80.5% oral bioavailability in healthy subjects, confirming that this morphinan scaffold is well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Samidorphan, a related morphinan with an ionizable amine, achieved 69% absolute oral bioavailability in healthy volunteers, supporting high oral F for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Noscapine, another morphinan alkaloid, had 30% absolute oral bioavailability in healthy volunteers, still above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Naltrexone, a less similar morphinan with different N-substitution and phenol/14-hydroxy groups, has low oral bioavailability (5–6%), but its low structural transferability limits its weight for the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most transferable evidence (codeine and codeine sulfate) shows high oral bioavailability (42–80%) for the same morphinan scaffold. Additional related morphinans (samidorphan, noscapine) also exceed 20%. The query's 6-keto, N-methyl, methoxy structure is expected to be at least as well absorbed as codeine. The low-F naltrexone example is structurally more distant and does not override the consistent high-F evidence. Therefore predict high (F ≥20%).",
  "evidence_gaps": [
    "No direct oral bioavailability record for hydrocodone itself; the closest evidence is codeine with Morgan similarity 0.5469.",
    "Human codeine F estimates vary widely (15–90%), though most are above 20%.",
    "No direct information on first-pass metabolism, CYP-mediated clearance, or efflux for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

